update public.article_cache set translation = '{"texts": ["The government has decided to allow a university tuition increase for the first time in 15 years. The Ministry of Education made this decision in order to address universities'' financial problems.", "Currently, Korean universities are facing a serious money-shortage problem. Student numbers are decreasing, but education costs keep rising. Especially regional universities'' situation is even more difficult.", "Tuition can only be raised within the range of the inflation rate (the rate at which prices rise). Universities can raise tuition by about 3% starting this year. However, students and parents are worried that the financial burden will grow.", "The government announced that it will expand scholarships for low-income (lower-bracket) students. It also emphasized that universities must use tuition to raise the quality of education.", "In the university community, various opinions are emerging about this decision. The universities welcome it, but students are planning protests against it."], "sentences": [{"text": "정부가 대학교 등록금 인상을 15년 만에 허용하기로 했어요.", "translation": "The government has decided to allow a university tuition increase for the first time in 15 years.", "vocab": [{"ko": "등록금", "en": "tuition", "note": ""}, {"ko": "인상", "en": "increase, hike", "note": ""}, {"ko": "허용하다", "en": "to permit, allow", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite. Hada-stem contracts 하+았 → 했.", "example_in_sentence": "했어요"}, {"type": "grammar", "label": "~만에 (after a duration)", "exp": "time elapsed. 15년 → 15년 만에 = \"after 15 years / for the first time in 15 years\".", "example_in_sentence": "15년 만에"}, {"type": "expression", "label": "~기로 하다 (decide to)", "exp": "decision. 허용하다 → 허용하기로 하다 = \"to decide to permit\"; past: 허용하기로 했어요 = \"decided to permit\".", "example_in_sentence": "허용하기로 했어요"}]}, {"text": "교육부는 대학의 재정 문제를 해결하기 위해 이런 결정을 내렸습니다.", "translation": "The Ministry of Education made this decision in order to address universities'' financial problems.", "vocab": [{"ko": "교육부", "en": "Ministry of Education", "note": ""}, {"ko": "재정", "en": "finances (institutional)", "note": ""}, {"ko": "해결하다", "en": "to solve", "note": ""}, {"ko": "결정", "en": "decision", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite. 내리다 → 내렸습니다 = \"made / handed down\".", "example_in_sentence": "내렸습니다"}, {"type": "grammar", "label": "~기 위해(서) (in order to)", "exp": "purpose. 해결하다 → 해결하기 위해 = \"in order to solve\".", "example_in_sentence": "해결하기 위해"}]}, {"text": "현재 한국 대학들은 심각한 돈 부족 문제를 겪고 있어요.", "translation": "Currently, Korean universities are facing a serious money-shortage problem.", "vocab": [{"ko": "심각하다", "en": "to be serious", "note": ""}, {"ko": "부족", "en": "shortage", "note": ""}, {"ko": "겪다", "en": "to undergo, experience", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 겪다 → 겪고 있다 = \"is experiencing\".", "example_in_sentence": "겪고 있어요"}]}, {"text": "학생 수는 줄어들고 있지만 교육 비용은 계속 늘어나고 있습니다.", "translation": "Student numbers are decreasing, but education costs keep rising.", "vocab": [{"ko": "줄어들다", "en": "to decrease", "note": ""}, {"ko": "비용", "en": "cost, expense", "note": ""}, {"ko": "늘어나다", "en": "to increase", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 줄어들다 → 줄어들고 있다 = \"is decreasing\".", "example_in_sentence": "줄어들고 있지만"}, {"type": "grammar", "label": "~지만 (but)", "exp": "contrast. 있다 → 있지만 = \"is, but ~\".", "example_in_sentence": "있지만"}]}, {"text": "특히 지방 대학들의 상황이 더욱 어려워요.", "translation": "In particular, the situation of regional universities is even more difficult.", "vocab": [{"ko": "지방", "en": "region, province", "note": ""}, {"ko": "상황", "en": "situation", "note": ""}, {"ko": "더욱", "en": "even more", "note": ""}, {"ko": "어렵다", "en": "to be difficult", "note": "ㅂ-irregular: 어렵+어 → 어려워"}], "analysis": [{"type": "grammar", "label": "ㅂ 불규칙 (ㅂ → 우/오)", "exp": "ㅂ-irregular. 어렵다 → 어려워(요). Stem-final ㅂ becomes 우/오 before 아/어.", "example_in_sentence": "어려워요"}]}, {"text": "등록금은 물가상승률(물건 값이 오르는 비율) 범위 내에서만 올릴 수 있어요.", "translation": "Tuition can only be raised within the range of the inflation rate (the rate at which prices rise).", "vocab": [{"ko": "물가상승률", "en": "inflation rate", "note": ""}, {"ko": "비율", "en": "rate, ratio", "note": ""}, {"ko": "범위", "en": "range, scope", "note": ""}, {"ko": "올리다", "en": "to raise", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability. 올리다 → 올릴 수 있다 = \"can raise\".", "example_in_sentence": "올릴 수 있어요"}, {"type": "grammar", "label": "~만 (only)", "exp": "limiter. 범위 내에서 → 범위 내에서만 = \"only within the range\".", "example_in_sentence": "범위 내에서만"}]}, {"text": "대학들은 올해부터 약 3% 정도 등록금을 인상할 수 있습니다.", "translation": "Universities can raise tuition by about 3% starting this year.", "vocab": [{"ko": "정도", "en": "about, roughly", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability. 인상하다 → 인상할 수 있다 = \"can raise\".", "example_in_sentence": "인상할 수 있습니다"}, {"type": "grammar", "label": "~부터 (from)", "exp": "starting from. 올해 → 올해부터 = \"starting this year\".", "example_in_sentence": "올해부터"}]}, {"text": "하지만 학생들과 학부모들은 경제적 부담이 커질 것을 걱정하고 있어요.", "translation": "However, students and parents are worried that the financial burden will grow.", "vocab": [{"ko": "학부모", "en": "parents of students", "note": ""}, {"ko": "부담", "en": "burden", "note": ""}, {"ko": "커지다", "en": "to become bigger", "note": "크다 + 아/어지다"}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 걱정하다 → 걱정하고 있다 = \"is worrying\".", "example_in_sentence": "걱정하고 있어요"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "formal \"and\". 학생들 → 학생들과 학부모들 = \"students and parents\".", "example_in_sentence": "학생들과 학부모들"}]}, {"text": "정부는 저소득층(소득이 적은 계층) 학생들을 위한 장학금을 늘리겠다고 발표했어요.", "translation": "The government announced that it will increase scholarships for low-income students (students from households that earn little).", "vocab": [{"ko": "저소득층", "en": "low-income bracket", "note": ""}, {"ko": "계층", "en": "social class, stratum", "note": ""}, {"ko": "장학금", "en": "scholarship", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite. 발표하다 → 발표했어요.", "example_in_sentence": "발표했어요"}, {"type": "grammar", "label": "~다고 하다 / ~다고 밝히다 / ~다고 강조하다 (indirect declarative + news reporting verbs)", "exp": "reported speech with future-intent quote. 늘리겠다 → 늘리겠다고 발표했어요 = \"announced that (it) will expand\".", "example_in_sentence": "늘리겠다고 발표했어요"}, {"type": "grammar", "label": "~을/를 위한 (for) [adnominal]", "exp": "attributive form of ~을 위해. 학생들을 → 학생들을 위한 장학금 = \"scholarships for students\".", "example_in_sentence": "학생들을 위한 장학금"}]}, {"text": "또한 대학들이 교육의 질을 높이는 데 등록금을 사용해야 한다고 강조했습니다.", "translation": "It also emphasized that universities must use tuition to raise the quality of education.", "vocab": [{"ko": "또한", "en": "also, in addition", "note": ""}, {"ko": "질", "en": "quality", "note": ""}, {"ko": "높이다", "en": "to raise, elevate", "note": ""}, {"ko": "강조하다", "en": "to emphasize", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "past formal-polite. 강조하다 → 강조했습니다 = \"emphasized\".", "example_in_sentence": "강조했습니다"}, {"type": "grammar", "label": "~아/어야 하다/되다 (must)", "exp": "obligation. 사용하다 → 사용해야 한다 = \"must use\". 하다 contracts to 해야.", "example_in_sentence": "사용해야 한다"}, {"type": "grammar", "label": "~다고 하다 / ~다고 밝히다 / ~다고 강조하다 (indirect declarative + news reporting verbs)", "exp": "reported speech. 사용해야 한다 → 사용해야 한다고 강조했습니다 = \"emphasized that (they) must use\".", "example_in_sentence": "사용해야 한다고 강조했습니다"}, {"type": "grammar", "label": "~ㄴ/는 데(에) (in V-ing / for V-ing)", "exp": "purpose/situation. 높이다 → 높이는 데 = \"in / for raising\". 높이는 데 등록금을 사용하다 = \"use tuition for raising (the quality)\".", "example_in_sentence": "높이는 데"}]}, {"text": "대학가에서는 이번 결정에 대해 다양한 의견이 나오고 있어요.", "translation": "In the university community, various opinions are emerging about this decision.", "vocab": [{"ko": "대학가", "en": "college town, university community", "note": ""}, {"ko": "다양하다", "en": "to be diverse", "note": ""}, {"ko": "의견", "en": "opinion", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 나오다 → 나오고 있다 = \"is coming out / emerging\".", "example_in_sentence": "나오고 있어요"}, {"type": "grammar", "label": "~에 대해(서)/대한 (about)", "exp": "topical. 결정 → 결정에 대해 = \"about the decision\".", "example_in_sentence": "결정에 대해"}]}, {"text": "대학 측은 환영하지만 학생들은 반대 시위를 계획하고 있습니다.", "translation": "The universities welcome it, but students are planning protests against it.", "vocab": [{"ko": "측", "en": "side, party", "note": ""}, {"ko": "환영하다", "en": "to welcome", "note": ""}, {"ko": "반대", "en": "opposition", "note": ""}, {"ko": "시위", "en": "protest, demonstration", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive. 계획하다 → 계획하고 있다 = \"is planning\".", "example_in_sentence": "계획하고 있습니다"}, {"type": "grammar", "label": "~지만 (but)", "exp": "contrast. 환영하다 → 환영하지만 = \"welcomes, but ~\".", "example_in_sentence": "환영하지만"}]}], "version": "s5"}', vocab = '[{"ko": "등록금", "en": "tuition", "note": ""}, {"ko": "인상", "en": "increase, hike", "note": ""}, {"ko": "허용하다", "en": "to permit, allow", "note": ""}, {"ko": "교육부", "en": "Ministry of Education", "note": ""}, {"ko": "재정", "en": "finances (institutional)", "note": ""}, {"ko": "해결하다", "en": "to solve", "note": ""}, {"ko": "결정", "en": "decision", "note": ""}, {"ko": "심각하다", "en": "to be serious", "note": ""}, {"ko": "부족", "en": "shortage", "note": ""}, {"ko": "겪다", "en": "to undergo, experience", "note": ""}, {"ko": "줄어들다", "en": "to decrease", "note": ""}, {"k