vocab": [{"ko": "효소", "en": "enzyme", "note": ""}], "grammar": [{"pattern": "~이 ~다고 알려져 있어요", "exp": "passive reporting structure; ''is known to''; commonly used for scientific/general knowledge", "example_in_sentence": "효소가 각질을 제거해준다고 알려져 있어요"}, {"pattern": "~어 주다", "exp": "benefactive; do a favor (here: remove for the benefit)", "example_in_sentence": "제거해준다"}], "analysis": []}, {"text": "과학자들은 이런 재료들의 효과를 연구하고 있어요.", "idx": 8, "translation": "Scientists are researching the effects of these ingredients.", "vocab": [{"ko": "과학자", "en": "scientist", "note": ""}, {"ko": "효과", "en": "effect, effectiveness", "note": ""}, {"ko": "연구하다", "en": "research, study", "note": "verb"}], "grammar": [{"pattern": "~고 있어요", "exp": "continuous present action", "example_in_sentence": "연구하고 있어요"}, {"pattern": "~의 (possessive particle)", "exp": "marks possession or relationship", "example_in_sentence": "재료들의 효과"}], "analysis": []}, {"text": "하지만 아직 확실한 증거는 부족한 상태예요.", "idx": 9, "translation": "However, solid evidence is still lacking.", "vocab": [{"ko": "하지만", "en": "however, but", "note": "conjunction"}, {"ko": "확실하다", "en": "certain, clear, solid", "note": "adjective"}, {"ko": "증거", "en": "evidence, proof", "note": ""}], "grammar": [{"pattern": "~은/은 상태예요", "exp": "resultative state; expresses current condition/state", "example_in_sentence": "부족한 상태예요"}, {"pattern": "~어도", "exp": "even though, still (concessive)", "example_in_sentence": "(implied in 하지만 - contrast)"}], "analysis": []}, {"text": "전문가들은 신중하게 사용하라고 조언해요.", "idx": 10, "translation": "Experts advise using it carefully.", "vocab": [{"ko": "전문가", "en": "expert, specialist", "note": ""}, {"ko": "신중하다", "en": "careful, cautious", "note": "adjective"}, {"ko": "조언하다", "en": "advise, counsel", "note": "verb"}], "grammar": [{"pattern": "~게 (adverbial ending)", "exp": "turns adjective/state into adverb modifying verb", "example_in_sentence": "신중하게"}, {"pattern": "~라고 조언하다", "exp": "reported speech + imperative; ''advise to do''", 